import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'

import {useHint} from '../../../../packages/Hints/Hints.hooks'
import type {Hint} from '../../../../packages/Hints/Hints.types'
import {HINT_CATEGORY, toHintId} from '../../../../packages/Hints/Hints.types'
import {sidebarSettings} from '../../SidebarPanel.slices'

import SidebarPinIcon from './SidebarPinIcon/SidebarPinIcon'

import styles from './SidebarHeader.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  sidebarName: ReactNode
  className?: string
  search: ReactNode
  headerButton?: ReactNode
}

const toggleSidebarHint: Hint = {
  id: toHintId('toggle-sidebar'),
  name: 'Toggle Sidebar',
  text: 'Press the S key to show or hide the sidebar anytime.',
  directions: [Directions.RIGHT_BOTTOM],
  offset: 16,
  category: HINT_CATEGORY.sidebar,
  obligatory: true,
}

function HeaderVisibilityButtons({className, search}: {className?: string; search: ReactNode}) {
  const dispatch = useAppDispatch()
  const sidebarCollapsed = useAppSelector(state => state.sidebarSettings.collapsed)

  return (
    <div
      className={classNames(className, styles.header, {
        [styles.collapsed]: sidebarCollapsed,
      })}
      role="presentation"
      onClick={
        sidebarCollapsed
          ? e => {
              // prevent immediate sidebar collapse when in overlay mode
              e.stopPropagation()
              dispatch(sidebarSettings.actions.toggleCollapseSidebar())
            }
          : undefined
      }
    >
      <div className={styles.searchWrapper}>
        <div className={styles.search}>{search}</div>
        {sidebarCollapsed && (
          <div className={styles.collapseIconButtonWrapper}>
            <SvgIcon
              className={styles.collapseIcon}
              icon={'double-chevron-right'}
              data-hint-container-id={toggleSidebarHint.id}
            />
          </div>
        )}
      </div>
    </div>
  )
}

const tooltipPopupProps = {
  directions: [Directions.RIGHT_BOTTOM],
  className: styles.tooltip,
  left: 4,
}

function SidebarHeader({sidebarName, className, search, headerButton}: Props) {
  const sidebarCollapsed = useAppSelector(state => state.sidebarSettings.collapsed)
  useHint(sidebarCollapsed ? toggleSidebarHint : null)

  return (
    <>
      <div className={classNames(styles.headerTitelRow)}>
        <div
          className={classNames(styles.sidebarHeader, {
            [styles.headerTitleCollapsed]: sidebarCollapsed,
          })}
        >
          <SidebarPinIcon />
          {sidebarName}
        </div>
        {headerButton && (
          <span
            className={classNames(styles.headerButton, {
              [styles.headerButtonCollapsed]: sidebarCollapsed,
            })}
          >
            {headerButton}
          </span>
        )}
      </div>
      {sidebarCollapsed ? (
        <Tooltip
          title={
            <>
              {'Expand'}
              <span className={styles.shortcut}>{'S'}</span>
            </>
          }
          hidden={!sidebarCollapsed}
          popupProps={tooltipPopupProps}
        >
          <HeaderVisibilityButtons className={className} search={search} />
        </Tooltip>
      ) : (
        <HeaderVisibilityButtons className={className} search={search} />
      )}
    </>
  )
}

export default SidebarHeader
