import {useCallback, useEffect, useState} from 'react'
import type {ScrollParams} from 'react-virtualized/dist/es/Grid'

import {sidebarSettings} from '../SidebarPanel.slices'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

export function useSidebar() {
  const [searchQuery, setSearchQuery] = useState('')
  const [searchActive, setSearchActive] = useState(false)

  const dispatch = useAppDispatch()
  const collapsed = useAppSelector(state => state.sidebarSettings.collapsed)

  const changeSidebarSearchQuery = useCallback((query: string) => {
    setSearchQuery(query)
  }, [])

  const changeSidebarSearchActive = useCallback(
    (active: boolean) => {
      setSearchActive(active)
      dispatch(sidebarSettings.actions.setAutoCollapseDisabled(active))

      if (!active) {
        setSearchQuery('')
      }
    },
    [dispatch],
  )

  useEffect(() => {
    if (collapsed && searchActive) {
      changeSidebarSearchActive(false)
    }
  }, [changeSidebarSearchActive, searchActive, collapsed])

  return {
    collapsed,
    searchQuery,
    searchActive,
    changeSidebarSearchQuery,
    changeSidebarSearchActive,
  }
}

type ScrollState = {
  isScrollAtStart: boolean
  isScrollAtEnd: boolean
}

export function useSidebarScroll(): [ScrollState | null, onScroll: (params: ScrollParams) => void] {
  const [state, setState] = useState<ScrollState | null>(null)

  const onScroll = useCallback(
    (params: ScrollParams) => {
      const isScrollAtStart = params.scrollTop === 0
      const isScrollAtEnd = params.scrollTop === params.scrollHeight - params.clientHeight

      if (isScrollAtStart !== state?.isScrollAtStart || isScrollAtEnd !== state?.isScrollAtEnd) {
        setState({isScrollAtStart, isScrollAtEnd})
      }
    },
    [state],
  )

  return [state, onScroll]
}
