import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import {sidebarSettings} from '../../../SidebarPanel.slices'

import styles from './SidebarPinIcon.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'
import SidebarIcon from 'src/svg/sidebar-20px.svg'
import SidebarFilledIcon from 'src/svg/sidebar-filled-20px.svg'
import {optionOrAltPlus} from 'src/utils/keys'

function SidebarPinIcon() {
  const dispatch = useAppDispatch()

  const isPinned = useAppSelector(state => state.sidebarSettings.pinned)
  const disabled = useAppSelector(state => state.sidebarSettings.pinDisabled)

  const title = disabled
    ? `You can't pin the sidebar because the screen is too narrow`
    : `${isPinned ? 'Unpin' : 'Pin'} sidebar`

  return (
    <Tooltip
      className={styles.wrapper}
      title={
        disabled ? (
          title
        ) : (
          <>
            {title}
            <span className={styles.shortcut}>{`${optionOrAltPlus}S`}</span>
          </>
        )
      }
      popupProps={{directions: [Directions.RIGHT_CENTER], left: 8}}
    >
      <IconButton
        icon={isPinned && !disabled ? SidebarFilledIcon : SidebarIcon}
        className={classNames(styles.pinIcon, disabled && styles.disabled)}
        onClick={() => dispatch(sidebarSettings.actions.togglePinSidebar())}
        disabled={disabled}
        title={''}
        aria-label={title}
      />
    </Tooltip>
  )
}

export default memo(SidebarPinIcon)
